@Component({
  selector: 'app-inventory-stock-control',
  standalone: true,
  imports: [CommonModule, FormsModule, DataGridComponent],
  template: `
    <section class="ui-surface stock-control" data-testid="inventory-stock-control">
      <header class="stock-control__header"><div><p class="eyebrow">{{ language.text('stockControlKicker') }}</p><h2>{{ language.text('stockControlTitle') }}</h2><p class="lede">{{ language.text('stockControlLead') }}</p></div><span class="status-badge status-badge--active">{{ language.text('stockControlServerAuthorized') }}</span></header>
      <div class="stock-control__toolbar">
        <label><span>{{ language.text('stockControlWarehouse') }}</span><select [(ngModel)]="warehouseId" (ngModelChange)="refresh()"><option value="">{{ language.text('stockControlChooseWarehouse') }}</option>@for (warehouse of warehouses(); track warehouse.warehouseId) {<option [value]="warehouse.warehouseId">{{ warehouse.displayName }}</option>}</select></label>
        <label><span>{{ language.text('stockControlProduct') }}</span><select [(ngModel)]="productId"><option value="">{{ language.text('stockControlChooseProduct') }}</option>@for (product of products(); track product.id) {<option [value]="product.id">{{ product.sku }} — {{ productName(product) }}</option>}</select></label>
        <button class="button button--quiet" type="button" (click)="refresh()">{{ language.text('refresh') }}</button>
      </div>
      @if (error()) { <p class="stock-control__error" role="alert">{{ error() }}</p> }

      <section class="reason-panel">
        <div class="list-heading"><div><h3>{{ language.text('stockControlReasonCatalogue') }}</h3><p class="form-note">{{ language.text('stockControlReasonCatalogueLead') }}</p></div><span>{{ reasonCatalogue().length }}</span></div>
        <form class="reason-form" (ngSubmit)="createReasonCode()"><input name="reasonCode" [placeholder]="language.text('code')" [(ngModel)]="newReason.code" required /><input name="reasonEnglish" [placeholder]="language.text('englishName')" [(ngModel)]="newReason.englishName" required /><input name="reasonArabic" dir="rtl" [placeholder]="language.text('arabicName')" [(ngModel)]="newReason.arabicName" required /><select name="reasonCategory" [(ngModel)]="newReason.category"><option value="Adjustment">{{ language.text('stockControlAdjustment') }}</option><option value="CountVariance">{{ language.text('stockControlCountVariance') }}</option><option value="StockIssue">{{ language.text('stockControlStockIssue') }}</option></select><button class="button button--primary" type="submit" [disabled]="!canWrite() || !newReason.code.trim() || !newReason.englishName.trim() || !newReason.arabicName.trim()">{{ language.text('stockControlCreateReason') }}</button></form>
        <app-data-grid [rows]="reasonCatalogue()" [columns]="reasonColumns()" [rowActions]="reasonActions" [language]="language.language()" [caption]="language.text('stockControlReasonCatalogue')" [countLabel]="gridLabel('count')" [emptyLabel]="language.text('stockControlNoReasonCodes')" [filterInputLabel]="gridLabel('filter')" [allValuesLabel]="gridLabel('all')" [clearFiltersLabel]="gridLabel('clear')" [pageSize]="reasonCatalogue().length || 1" [showPager]="false" (rowAction)="runReasonAction($event)" />
      </section>

      <div class="stock-control__grid">
        <form class="control-form" (ngSubmit)="createAdjustment()"><h3>{{ language.text('stockControlAdjustment') }}</h3><label><span>{{ language.text('stockControlDirection') }}</span><select name="direction" [(ngModel)]="adjustment.direction"><option value="Increase">{{ language.text('stockControlIncrease') }}</option><option value="Decrease">{{ language.text('stockControlDecrease') }}</option></select></label><label><span>{{ language.text('quantity') }}</span><input name="quantity" type="number" min="0.00000001" step="any" [(ngModel)]="adjustment.quantity" required /></label><label><span>{{ language.text('stockControlReason') }}</span><select name="reason" [(ngModel)]="adjustment.reasonCode" required><option value="">{{ language.text('stockControlChooseReason') }}</option>@for (reason of adjustmentReasons(); track reason.id) {<option [value]="reason.code">{{ reason.code }} — {{ reasonName(reason) }}</option>}</select></label><label><span>{{ language.text('stockControlTrackingOptional') }}</span><input name="tracking" [(ngModel)]="adjustment.trackingIdentity" /></label><button class="button button--primary" type="submit" [disabled]="!canWrite() || adjustment.quantity <= 0">{{ language.text('stockControlCreateDraft') }}</button></form>
        <form class="control-form" (ngSubmit)="createCount()"><h3>{{ language.text('stockControlCount') }}</h3><label><span>{{ language.text('stockControlCountType') }}</span><select name="countType" [(ngModel)]="countType"><option value="Cycle">{{ language.text('stockControlCycleCount') }}</option><option value="Full">{{ language.text('stockControlFullSnapshot') }}</option></select></label><label><span>{{ language.text('stockControlCounter') }}</span><input name="counter" [value]="actorId" readonly /></label><label><span>{{ language.text('stockControlReviewerOptional') }}</span><input name="reviewer" [(ngModel)]="reviewerId" [placeholder]="language.text('stockControlReviewerHint')" /></label><p class="form-note">{{ language.text('stockControlCountInstruction') }}</p><button class="button button--primary" type="submit" [disabled]="!canWrite() || !productId || !actorId">{{ language.text('stockControlOpenCount') }}</button></form>
        <form class="control-form" (ngSubmit)="createIssue()"><h3>{{ language.text('stockControlStockIssue') }}</h3><label><span>{{ language.text('stockControlDestinationUse') }}</span><input name="destination" maxlength="2048" [(ngModel)]="issue.destinationUseDescription" required /></label><label><span>{{ language.text('quantity') }}</span><input name="issueQuantity" type="number" min="0.00000001" step="any" [(ngModel)]="issue.quantity" required /></label><label><span>{{ language.text('stockControlReason') }}</span><select name="issueReason" [(ngModel)]="issue.reasonCode" required><option value="">{{ language.text('stockControlChooseReason') }}</option>@for (reason of issueReasons(); track reason.id) {<option [value]="reason.code">{{ reason.code }} — {{ reasonName(reason) }}</option>}</select></label><label><span>{{ language.text('stockControlTrackingOptional') }}</span><input name="issueTracking" [(ngModel)]="issue.trackingIdentity" /></label><button class="button button--primary" type="submit" [disabled]="!canWrite() || issue.quantity <= 0">{{ language.text('stockControlCreateDraft') }}</button></form>
      </div>

      <ng-template #reasonEditor let-reason let-column="column">
        @if (column.key === 'category') { <select [name]="'reason-category-' + reason.id" [(ngModel)]="reasonDrafts[reason.id].category"><option value="Adjustment">{{ language.text('stockControlAdjustment') }}</option><option value="CountVariance">{{ language.text('stockControlCountVariance') }}</option><option value="StockIssue">{{ language.text('stockControlStockIssue') }}</option></select> }
        @if (column.key === 'englishName') { <input [name]="'reason-en-' + reason.id" [(ngModel)]="reasonDrafts[reason.id].englishName" /> }
        @if (column.key === 'arabicName') { <input dir="rtl" [name]="'reason-ar-' + reason.id" [(ngModel)]="reasonDrafts[reason.id].arabicName" /> }
      </ng-template>
      <ng-template #adjustmentWorkflow let-record>
        <div class="control-actions">
          @if (record.status === 'Draft') { <button type="button" (click)="submitAdjustment(record)">{{ language.text('stockControlSubmit') }}</button> }
          @if (record.status === 'PendingApproval') { <button type="button" (click)="approveAdjustment(record)">{{ language.text('stockControlApprove') }}</button><button type="button" (click)="rejectAdjustment(record)">{{ language.text('stockControlReject') }}</button> }
          @if (record.status === 'Approved') { <button type="button" (click)="postAdjustment(record)">{{ language.text('stockControlPost') }}</button> }
          <button type="button" (click)="loadAdjustmentHistory(record.id)">{{ language.text('stockControlHistory') }}</button>
        </div>
        @if (historyFor(record.id).length) { <ol class="history-list">@for (event of historyFor(record.id); track event.id) { <li>{{ historyActionLabel(event.action) }} &middot; {{ statusLabel(event.fromStatus) }} &middot; {{ statusLabel(event.toStatus) }} &middot; {{ event.occurredAt | date:'short' }}</li> }</ol> }
      </ng-template>
      <ng-template #countWorkflow let-record>
        @if (record.status === 'Draft' && record.assignedCounterId === actorId) {
          <div class="count-observations"><p class="form-note">{{ language.text('stockControlPhysicalQuantity') }}</p>@for (line of currentLines(record); track line.id) { <label class="count-line"><span>{{ line.productSku }} &middot; {{ line.unitOfMeasureCode }}@if (line.trackingIdentity) { &middot; {{ line.trackingIdentity }}}</span><input type="number" min="0" step="any" [name]="'count-' + line.id" [(ngModel)]="countedQuantities[line.id]" required /></label> }<button type="button" (click)="submitCount(record)">{{ language.text('stockControlSubmitObservations') }}</button></div>
        }
        @if (record.status !== 'Draft' || record.assignedCounterId !== actorId) {
          <div class="count-review">@for (line of currentLines(record); track line.id) { <div class="count-line"><span>{{ line.productSku }} &middot; {{ line.unitOfMeasureCode }}</span><small>{{ language.text('stockControlExpected') }}: {{ line.expectedQuantity ?? '\u2014' }} &middot; {{ language.text('stockControlCounted') }}: {{ line.countedQuantity ?? '\u2014' }} &middot; {{ language.text('stockControlVariance') }}: {{ line.variance ?? '\u2014' }}</small>@if (record.status === 'PendingApproval' && line.variance !== null && line.variance !== 0 && !line.varianceReasonCode) { <select [name]="'variance-' + line.id" [(ngModel)]="varianceReasonCodes[line.id]"><option value="">{{ language.text('stockControlChooseReason') }}</option>@for (reason of varianceReasons(); track reason.id) { <option [value]="reason.code">{{ reason.code }} &middot; {{ reasonName(reason) }}</option> }</select><button type="button" (click)="recordVarianceReason(record, line)">{{ language.text('stockControlRecordReason') }}</button> }</div> }</div>
        }
        <div class="control-actions">@if (record.status === 'PendingApproval') { <button type="button" (click)="approveCount(record)">{{ language.text('stockControlApprove') }}</button><button type="button" (click)="rejectCount(record)">{{ language.text('stockControlReject') }}</button> } @if (record.status === 'Submitted') { <button type="button" (click)="postCount(record)">{{ language.text('stockControlFinalize') }}</button> } @if (record.status === 'Approved') { <button type="button" (click)="postCount(record)">{{ language.text('stockControlPost') }}</button> } @if (record.status === 'PendingApproval' || record.status === 'Approved') { <button type="button" (click)="recount(record)">{{ language.text('stockControlRequestRecount') }}</button> } @if (record.status === 'ResnapshotRequired') { <button type="button" (click)="resnapshot(record)">{{ language.text('stockControlResnapshot') }}</button> }<button type="button" (click)="loadCountHistory(record.id)">{{ language.text('stockControlHistory') }}</button></div>
        @if (historyFor(record.id).length) { <ol class="history-list">@for (event of historyFor(record.id); track event.id) { <li>{{ historyActionLabel(event.action) }} &middot; {{ statusLabel(event.fromStatus) }} &middot; {{ statusLabel(event.toStatus) }} &middot; {{ event.occurredAt | date:'short' }}</li> }</ol> }
      </ng-template>
      <ng-template #issueWorkflow let-record>
        <div class="control-actions">@if (record.status === 'Draft') { <button type="button" (click)="submitIssue(record)">{{ language.text('stockControlSubmit') }}</button> } @if (record.status === 'PendingApproval') { <button type="button" (click)="approveIssue(record)">{{ language.text('stockControlApprove') }}</button><button type="button" (click)="rejectIssue(record)">{{ language.text('stockControlReject') }}</button> } @if (record.status === 'Approved') { <button type="button" (click)="postIssue(record)">{{ language.text('stockControlPost') }}</button> }<button type="button" (click)="loadIssueHistory(record.id)">{{ language.text('stockControlHistory') }}</button></div>
        @if (historyFor(record.id).length) { <ol class="history-list">@for (event of historyFor(record.id); track event.id) { <li>{{ historyActionLabel(event.action) }} &middot; {{ statusLabel(event.fromStatus) }} &middot; {{ statusLabel(event.toStatus) }} &middot; {{ event.occurredAt | date:'short' }}</li> }</ol> }
      </ng-template>
      <ng-template #correctionWorkflow let-movement>
        @if (movement.correctionOfMovementId) { <span class="status-badge">{{ language.text('stockControlCorrectionOf') }} {{ movement.correctionOfMovementId }}</span> }
        @else if (isEligibleCorrection(movement) && !hasCorrection(movement)) { <label><span class="sr-only">{{ language.text('stockControlReason') }}</span><select [name]="'correction-reason-' + movement.id" [(ngModel)]="correctionReasonCodes[movement.id]"><option value="">{{ language.text('stockControlChooseReason') }}</option>@for (reason of correctionReasons(movement); track reason.id) { <option [value]="reason.code">{{ reason.code }} &middot; {{ reasonName(reason) }}</option> }</select></label><input [name]="'correction-note-' + movement.id" [(ngModel)]="correctionNotes[movement.id]" [placeholder]="language.text('stockControlOptionalExplanation')" /><button type="button" (click)="correctMovement(movement)">{{ language.text('stockControlCorrectMovement') }}</button> }
        @else if (hasCorrection(movement)) { <span class="status-badge">{{ language.text('stockControlAlreadyCorrected') }}</span> }
      </ng-template>
      <div class="stock-control__lists">
        <section><div class="list-heading"><h3>{{ language.text('stockControlAdjustments') }}</h3><span>{{ adjustments().length }}</span></div><app-data-grid [rows]="adjustments()" [columns]="adjustmentColumns()" [rowActions]="[]" [language]="language.language()" [caption]="language.text('stockControlAdjustments')" [countLabel]="gridLabel('count')" [emptyLabel]="language.text('stockControlNoAdjustments')" [filterInputLabel]="gridLabel('filter')" [allValuesLabel]="gridLabel('all')" [clearFiltersLabel]="gridLabel('clear')" [pageSize]="adjustments().length || 1" [showPager]="false" /></section>
        <section><div class="list-heading"><h3>{{ language.text('stockControlCounts') }}</h3><span>{{ counts().length }}</span></div><app-data-grid [rows]="counts()" [columns]="countColumns()" [rowActions]="[]" [language]="language.language()" [caption]="language.text('stockControlCounts')" [countLabel]="gridLabel('count')" [emptyLabel]="language.text('stockControlNoCounts')" [filterInputLabel]="gridLabel('filter')" [allValuesLabel]="gridLabel('all')" [clearFiltersLabel]="gridLabel('clear')" [pageSize]="counts().length || 1" [showPager]="false" /></section>
        <section><div class="list-heading"><h3>{{ language.text('stockControlIssues') }}</h3><span>{{ issues().length }}</span></div><app-data-grid [rows]="issues()" [columns]="issueColumns()" [rowActions]="[]" [language]="language.language()" [caption]="language.text('stockControlIssues')" [countLabel]="gridLabel('count')" [emptyLabel]="language.text('stockControlNoIssues')" [filterInputLabel]="gridLabel('filter')" [allValuesLabel]="gridLabel('all')" [clearFiltersLabel]="gridLabel('clear')" [pageSize]="issues().length || 1" [showPager]="false" /></section>
      </div>

      <section class="ledger-panel"><div class="list-heading"><div><h3>{{ language.text('stockControlEligibleCorrections') }}</h3><p class="form-note">{{ language.text('stockControlEligibleCorrectionsLead') }}</p></div><span>{{ ledgerMovements().length }}</span></div><app-data-grid [rows]="ledgerMovements()" [columns]="correctionColumns()" [rowActions]="[]" [language]="language.language()" [caption]="language.text('stockControlEligibleCorrections')" [countLabel]="gridLabel('count')" [emptyLabel]="language.text('stockControlNoLedgerMovements')" [filterInputLabel]="gridLabel('filter')" [allValuesLabel]="gridLabel('all')" [clearFiltersLabel]="gridLabel('clear')" [pageSize]="ledgerMovements().length || 1" [showPager]="false" /></section>
    </section>
  `,
  styles: [`.stock-control{padding:1.35rem;margin-top:1rem}.stock-control__header,.stock-control__toolbar,.list-heading,.control-row{display:flex;align-items:center;justify-content:space-between;gap:1rem}.stock-control__toolbar{border-top:1px solid #e8efec;border-bottom:1px solid #e8efec;padding:1rem 0;margin:1rem 0}.stock-control__toolbar label,.control-form label{display:grid;gap:.3rem;color:var(--muted);font-size:.76rem;font-weight:700;flex:1}.stock-control select,.stock-control input{width:100%;border:1px solid #d7e0dd;border-radius:.55rem;padding:.6rem;background:#fff}.stock-control__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.control-form{display:grid;gap:.65rem;background:#f5f9f7;border-radius:.7rem;padding:1rem}.control-form h3{margin:0}.form-note{font-size:.76rem;color:var(--muted);line-height:1.45}.stock-control__lists{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;margin-top:1.2rem}.stock-control__lists>section{border-top:2px solid #dce9e4;padding-top:.7rem}.list-heading h3{margin:.2rem 0}.list-heading span{color:var(--muted);font-weight:800}.control-row{border-top:1px solid #e8efec;padding:.7rem 0;align-items:flex-start;flex-wrap:wrap}.control-row>div:first-child{min-width:0;flex:1}.control-row small{display:block;color:var(--muted);margin-top:.2rem}.control-actions{display:flex;gap:.3rem;flex-wrap:wrap}.control-actions button,.count-observations button,.count-review button,.reason-row button,.ledger-panel button{border:0;background:transparent;color:#2e7263;font-weight:800;cursor:pointer}.count-observations,.count-review{display:grid;gap:.45rem;width:100%;background:#f5f9f7;padding:.7rem;border-radius:.5rem}.count-line{display:grid;grid-template-columns:1fr minmax(7rem,10rem);align-items:center;gap:.5rem;color:#29433b;font-size:.8rem}.count-line small{grid-column:1 / -1}.count-review select,.reason-row select,.reason-row input,.reason-form input,.reason-form select,.ledger-panel select,.ledger-panel input{padding:.45rem;border:1px solid #d7e0dd;border-radius:.45rem}.stock-control__error{color:#a33b34;background:#fff0ee;padding:.7rem;border-radius:.5rem}.empty-copy{color:var(--muted);font-size:.8rem}.reason-panel,.ledger-panel{margin-top:1.2rem;border-top:2px solid #dce9e4;padding-top:.7rem}.reason-form{display:grid;grid-template-columns:1fr 1.4fr 1.4fr 1fr auto;gap:.5rem;margin:.7rem 0}.reason-list{display:grid;gap:.35rem}.reason-row{display:grid;grid-template-columns:1fr 1fr 1.4fr 1.4fr auto auto auto;align-items:center;gap:.45rem;border-top:1px solid #e8efec;padding:.55rem 0}.history-list{width:100%;margin:.2rem 0 0;padding-left:1.2rem;color:var(--muted);font-size:.75rem}.ledger-panel .control-row{align-items:center}@media(max-width:1050px){.stock-control__grid,.stock-control__lists{grid-template-columns:1fr}.stock-control__toolbar{flex-wrap:wrap}.stock-control__toolbar label{min-width:14rem}.reason-form,.reason-row{grid-template-columns:1fr}.reason-row strong{margin-top:.4rem}}`],
  styleUrls: ['./inventory-stock-control-contrast.scss'],
})
export class InventoryStockControlComponent implements OnInit {
  @ViewChild('reasonEditor', { static: true }) private reasonEditor!: TemplateRef<any>;
  @ViewChild('adjustmentWorkflow', { static: true }) private adjustmentWorkflow!: TemplateRef<any>;
  @ViewChild('countWorkflow', { static: true }) private countWorkflow!: TemplateRef<any>;
  @ViewChild('issueWorkflow', { static: true }) private issueWorkflow!: TemplateRef<any>;
  @ViewChild('correctionWorkflow', { static: true }) private correctionWorkflow!: TemplateRef<any>;
  private readonly inventory = inject(InventoryService);
  private readonly masterData = inject(MasterDataService);
  private readonly auth = inject(AuthService);
  private readonly languageService = inject(LanguageService);
  readonly language = {
    language: (): StockControlLanguage => this.languageService.language(),
    text: (key: string): string => key.startsWith('stockControl') ? this.stockText(key) : this.languageService.text(key as TranslationKey),
  };
  readonly warehouses = signal<InventoryWarehouseOption[]>([]);
  readonly products = signal<ProductRecord[]>([]);
  readonly reasonCatalogue = signal<InventoryReasonCode[]>([]);
  readonly adjustmentReasons = signal<InventoryReasonCode[]>([]);
  readonly issueReasons = signal<InventoryReasonCode[]>([]);
  readonly varianceReasons = signal<InventoryReasonCode[]>([]);
  readonly adjustments = signal<InventoryAdjustment[]>([]);
  readonly counts = signal<InventoryCount[]>([]);
  readonly issues = signal<InventoryStockIssue[]>([]);
  readonly ledgerMovements = signal<InventoryMovement[]>([]);
  readonly reasonColumns = signal<DataGridColumn<InventoryReasonCode>[]>([]);
  readonly adjustmentColumns = signal<DataGridColumn<InventoryAdjustment>[]>([]);
  readonly countColumns = signal<DataGridColumn<InventoryCount>[]>([]);
  readonly issueColumns = signal<DataGridColumn<InventoryStockIssue>[]>([]);
  readonly correctionColumns = signal<DataGridColumn<InventoryMovement>[]>([]);
  readonly histories = signal<Record<string, InventoryControlHistory[]>>({});
  readonly error = signal('');
  countedQuantities: Record<string, number | null> = {};
  varianceReasonCodes: Record<string, string> = {};
  correctionReasonCodes: Record<string, string> = {};
  correctionNotes: Record<string, string> = {};
  reasonDrafts: Record<string, { englishName: string; arabicName: string; category: InventoryReasonCategory }> = {};
  warehouseId = '';
  productId = '';
  countType: 'Cycle' | 'Full' = 'Cycle';
  actorId = '';
  reviewerId = '';
  newReason = { code: '', englishName: '', arabicName: '', category: 'Adjustment' as InventoryReasonCategory };
  adjustment = { direction: 'Increase' as 'Increase' | 'Decrease', quantity: 0, reasonCode: '', trackingIdentity: '' };
  issue = { destinationUseDescription: '', quantity: 0, reasonCode: '', trackingIdentity: '' };

  gridLabel(key: 'count' | 'filter' | 'all' | 'clear'): string {
    const labels = this.language.language() === 'ar'
      ? { count: '\u0633\u062c\u0644\u0627\u062a', filter: '\u062a\u0635\u0641\u064a\u0629', all: '\u0627\u0644\u0643\u0644', clear: '\u0645\u0633\u062d \u0639\u0648\u0627\u0645\u0644 \u0627\u0644\u062a\u0635\u0641\u064a\u0629' }
      : { count: 'records', filter: 'Filter', all: 'All', clear: 'Clear filters' };
    return labels[key];
  }

  stockText(key: string): string {
    const locale = this.languageService.language();
    return stockControlTranslations[locale][key] ?? stockControlTranslations.en[key] ?? key;
  }

  ngOnInit(): void { this.actorId = this.auth.session()?.actorId ?? ''; this.initializeGridColumns(); void this.load(); }
  private initializeGridColumns(): void {
    this.reasonColumns.set([
      { key: 'code', label: this.language.text('code'), value: row => row.code, filter: 'text' },
      { key: 'category', label: this.language.text('type'), value: row => this.reasonDrafts[row.id]?.category ?? row.category, cellTemplate: this.reasonEditor },
      { key: 'englishName', label: this.language.text('englishName'), value: row => this.reasonDrafts[row.id]?.englishName ?? row.englishName, cellTemplate: this.reasonEditor },
      { key: 'arabicName', label: this.language.text('arabicName'), value: row => this.reasonDrafts[row.id]?.arabicName ?? row.arabicName, cellTemplate: this.reasonEditor },
      { key: 'status', label: this.language.text('status'), value: row => row.isActive ? 'Active' : 'Inactive', display: row => this.language.text(row.isActive ? 'active' : 'inactiveStatus'), badge: true, filter: 'select', filterOptions: [{ value: 'Active', label: this.language.text('active') }, { value: 'Inactive', label: this.language.text('inactiveStatus') }] },
    ]);
    this.adjustmentColumns.set([
      { key: 'product', label: this.language.text('stockControlProduct'), value: row => row.lines[0]?.productSku ?? '—', filter: 'text' },
      { key: 'direction', label: this.language.text('stockControlDirection'), value: row => this.directionLabel(row.lines[0]?.direction) },
      { key: 'quantity', label: this.language.text('quantity'), value: row => row.lines[0]?.quantity ?? 0, align: 'end', filter: 'number-range' },
      { key: 'reason', label: this.language.text('stockControlReason'), value: row => row.lines[0]?.reasonCode ?? '—' },
      { key: 'status', label: this.language.text('status'), value: row => row.status, display: row => this.statusLabel(row.status), badge: true, filter: 'text' },
      { key: 'workflow', label: this.language.text('stockControlHistory'), value: row => row.status, cellTemplate: this.adjustmentWorkflow, width: 420 },
    ]);
    this.countColumns.set([
      { key: 'type', label: this.language.text('stockControlCountType'), value: row => row.countType, display: row => this.countTypeLabel(row.countType), filter: 'text' },
      { key: 'round', label: this.language.text('stockControlRound'), value: row => row.currentRoundGeneration, align: 'end' },
      { key: 'lines', label: this.language.text('stockControlLines'), value: row => row.lines.length, align: 'end' },
      { key: 'snapshot', label: this.language.text('date'), value: row => row.snapshotCutoff, filter: 'date-range' },
      { key: 'status', label: this.language.text('status'), value: row => row.status, display: row => this.statusLabel(row.status), badge: true, filter: 'text' },
      { key: 'workflow', label: this.language.text('stockControlHistory'), value: row => row.status, cellTemplate: this.countWorkflow, width: 560 },
    ]);
    this.issueColumns.set([
      { key: 'destination', label: this.language.text('stockControlDestinationUse'), value: row => row.destinationUseDescription, filter: 'text' },
      { key: 'product', label: this.language.text('stockControlProduct'), value: row => row.lines[0]?.productSku ?? '—' },
      { key: 'quantity', label: this.language.text('quantity'), value: row => row.lines[0]?.quantity ?? 0, align: 'end', filter: 'number-range' },
      { key: 'reason', label: this.language.text('stockControlReason'), value: row => row.lines[0]?.reasonCode ?? '—' },
      { key: 'status', label: this.language.text('status'), value: row => row.status, display: row => this.statusLabel(row.status), badge: true, filter: 'text' },
      { key: 'workflow', label: this.language.text('stockControlHistory'), value: row => row.status, cellTemplate: this.issueWorkflow, width: 420 },
    ]);
    this.correctionColumns.set([
      { key: 'date', label: this.language.text('date'), value: row => row.effectiveDate, filter: 'date-range' },
      { key: 'product', label: this.language.text('stockControlProduct'), value: row => row.productSku, filter: 'text' },
      { key: 'source', label: this.language.text('stockControlMovement'), value: row => this.sourceTypeLabel(row.sourceType), secondaryText: row => row.sourceReference || row.id },
      { key: 'direction', label: this.language.text('stockControlDirection'), value: row => this.directionLabel(row.direction) },
      { key: 'quantity', label: this.language.text('quantity'), value: row => row.quantity, align: 'end', filter: 'number-range' },
      { key: 'workflow', label: this.language.text('stockControlCorrectMovement'), value: row => row.id, cellTemplate: this.correctionWorkflow, width: 460 },
    ]);
  }
  get reasonActions() { return [
    { key: 'save', label: this.language.text('stockControlSave') },
    { key: 'activate', label: this.language.text('stockControlActivate'), visible: (row: InventoryReasonCode) => !row.isActive },
    { key: 'deactivate', label: this.language.text('stockControlDeactivate'), visible: (row: InventoryReasonCode) => row.isActive },
  ]; }
  runReasonAction(action: DataGridAction<InventoryReasonCode>): void { if (action.action === 'save') void this.updateReasonCode(action.row); else if (action.action === 'activate' || action.action === 'deactivate') void this.toggleReasonCode(action.row); }
  private selectedWarehouse(): InventoryWarehouseOption | undefined { return this.warehouses().find(item => item.warehouseId === this.warehouseId); }
  private selectedProduct(): ProductRecord | undefined { return this.products().find(item => item.id === this.productId); }
  canWrite(): boolean { return !!this.selectedWarehouse() && !!this.selectedProduct(); }
  currentLines(record: InventoryCount): InventoryCountLine[] { return record.lines.filter(line => line.isCurrentRound); }
  historyFor(id: string): InventoryControlHistory[] { return this.histories()[id] ?? []; }
  productName(product: ProductRecord): string { return this.language.language() === 'ar' ? product.arabicName || product.englishName || '' : product.englishName || product.arabicName || ''; }
  reasonName(reason: InventoryReasonCode): string { return this.language.language() === 'ar' ? reason.arabicName || reason.englishName : reason.englishName || reason.arabicName; }
  statusLabel(status: string): string { const keys: Record<string, string> = { Draft: 'stockControlStatusDraft', Submitted: 'stockControlStatusSubmitted', PendingApproval: 'stockControlStatusPendingApproval', Approved: 'stockControlStatusApproved', Rejected: 'stockControlStatusRejected', ReturnedForChange: 'stockControlStatusReturnedForChange', Posted: 'stockControlStatusPosted', Corrected: 'stockControlStatusCorrected', RecountRequired: 'stockControlStatusRecountRequired', ResnapshotRequired: 'stockControlStatusResnapshotRequired', Blocked: 'stockControlStatusBlocked' }; return this.language.text(keys[status] ?? 'stockControlStatusBlocked'); }
  historyActionLabel(action: string): string { const keys: Record<string, string> = { Created: 'stockControlHistoryCreated', Submitted: 'stockControlHistorySubmitted', Approved: 'stockControlHistoryApproved', Rejected: 'stockControlHistoryRejected', ReturnedForChange: 'stockControlHistoryReturnedForChange', Posted: 'stockControlHistoryPosted', PostBlocked: 'stockControlHistoryPostBlocked', Corrected: 'stockControlHistoryCorrected', Snapshot: 'stockControlHistorySnapshot', CountSubmitted: 'stockControlHistoryCountSubmitted', RecountRequested: 'stockControlHistoryRecountRequested', Resnapshot: 'stockControlHistoryResnapshot', VarianceReasonRecorded: 'stockControlHistoryVarianceReasonRecorded', AuthorizationDenied: 'stockControlHistoryAuthorizationDenied', TrackingRejected: 'stockControlHistoryTrackingRejected', IdempotencyConflict: 'stockControlHistoryIdempotencyConflict', ConcurrencyConflict: 'stockControlHistoryConcurrencyConflict' }; return this.language.text(keys[action] ?? 'stockControlHistory'); }
  directionLabel(direction: string | undefined): string { return this.language.text(direction === 'Decrease' || direction === 'Outbound' ? 'stockControlDecrease' : 'stockControlIncrease'); }
  countTypeLabel(countType: string): string { return this.language.text(countType === 'Full' ? 'stockControlFullSnapshot' : 'stockControlCycleCount'); }
  sourceTypeLabel(sourceType: string): string { const keys: Record<string, string> = { StockAdjustment: 'stockControlMovementStockAdjustment', InventoryCountVariance: 'stockControlMovementCountVariance', StockIssue: 'stockControlMovementStockIssue' }; return this.language.text(keys[sourceType] ?? 'stockControlMovement'); }
  private setReasonDrafts(reasons: InventoryReasonCode[]): void { for (const reason of reasons) this.reasonDrafts[reason.id] = { englishName: reason.englishName, arabicName: reason.arabicName, category: reason.category }; }
  private async load(): Promise<void> { try { const [warehouses, products] = await Promise.all([firstValueFrom(this.inventory.warehouses()), firstValueFrom(this.masterData.list('products'))]); this.warehouses.set(warehouses); this.products.set(products.filter((item): item is ProductRecord => 'sku' in item && item.isInventoryRelevant)); if (warehouses[0]) { this.warehouseId = warehouses[0].warehouseId; this.productId = this.products()[0]?.id ?? ''; await this.refresh(); } } catch { this.error.set(this.language.text('stockControlLoadFailed')); } }
  async refresh(): Promise<void> { const warehouse = this.selectedWarehouse(); if (!warehouse) return; try { const filters = { warehouseId: warehouse.warehouseId, companyId: warehouse.companyId, branchId: warehouse.branchId || undefined }; const [adjustments, counts, issues, allReasons, ledger] = await Promise.all([firstValueFrom(this.inventory.adjustments(filters)), firstValueFrom(this.inventory.counts(filters)), firstValueFrom(this.inventory.stockIssues(filters)), firstValueFrom(this.inventory.reasonCodes(undefined, true)), firstValueFrom(this.inventory.ledger(filters))]); this.adjustments.set(adjustments); this.counts.set(counts); this.issues.set(issues); this.reasonCatalogue.set(allReasons); this.setReasonDrafts(allReasons); this.adjustmentReasons.set(allReasons.filter(item => item.category === 'Adjustment' && item.isActive)); this.issueReasons.set(allReasons.filter(item => item.category === 'StockIssue' && item.isActive)); this.varianceReasons.set(allReasons.filter(item => item.category === 'CountVariance' && item.isActive)); this.ledgerMovements.set(ledger); } catch { this.error.set(this.language.text('stockControlContextUnavailable')); } }
  async createReasonCode(): Promise<void> { if (!this.canWrite() || !this.newReason.code.trim() || !this.newReason.englishName.trim() || !this.newReason.arabicName.trim()) return; try { await this.inventory.createReasonCode({ code: this.newReason.code.trim(), englishName: this.newReason.englishName.trim(), arabicName: this.newReason.arabicName.trim(), category: this.newReason.category }); this.newReason = { code: '', englishName: '', arabicName: '', category: 'Adjustment' }; await this.refresh(); } catch { this.error.set(this.language.text('stockControlReasonCreateFailed')); } }
  async updateReasonCode(reason: InventoryReasonCode): Promise<void> { const draft = this.reasonDrafts[reason.id]; if (!draft || !draft.englishName.trim() || !draft.arabicName.trim()) return; try { await this.inventory.updateReasonCode(reason.id, reason.version, { englishName: draft.englishName.trim(), arabicName: draft.arabicName.trim(), category: draft.category, isActive: reason.isActive }); await this.refresh(); } catch { this.error.set(this.language.text('stockControlReasonUpdateFailed')); } }
  async toggleReasonCode(reason: InventoryReasonCode): Promise<void> { const draft = this.reasonDrafts[reason.id]; if (!draft) return; try { await this.inventory.updateReasonCode(reason.id, reason.version, { englishName: draft.englishName, arabicName: draft.arabicName, category: draft.category, isActive: !reason.isActive }); await this.refresh(); } catch { this.error.set(this.language.text('stockControlReasonToggleFailed')); } }
  async createAdjustment(): Promise<void> { const warehouse = this.selectedWarehouse(); const product = this.selectedProduct(); if (!warehouse || !product || !this.adjustment.reasonCode || this.adjustment.quantity <= 0) return; try { await this.inventory.createAdjustment({ companyId: warehouse.companyId, branchId: warehouse.branchId, warehouseId: warehouse.warehouseId, evidenceReference: null, lines: [{ productId: product.id, unitOfMeasureId: product.baseUnitOfMeasureId, direction: this.adjustment.direction, quantity: this.adjustment.quantity, reasonCode: this.adjustment.reasonCode, trackingIdentity: this.adjustment.trackingIdentity || null, evidenceReference: null }] }); this.adjustment.quantity = 0; await this.refresh(); } catch { this.error.set(this.language.text('stockControlAdjustmentCreateFailed')); } }
  async submitAdjustment(record: InventoryAdjustment): Promise<void> { try { await this.inventory.submitAdjustment(record.id, record.version); await this.refresh(); } catch { this.error.set(this.language.text('stockControlAdjustmentSubmitFailed')); } }
  async approveAdjustment(record: InventoryAdjustment): Promise<void> { try { await this.inventory.approveAdjustment(record.id, record.version); await this.refresh(); } catch { this.error.set(this.language.text('stockControlApprovalFailed')); } }
  async rejectAdjustment(record: InventoryAdjustment): Promise<void> { try { await this.inventory.rejectAdjustment(record.id, record.version, { reason: this.language.text('stockControlReviewerRejectionReason') }); await this.refresh(); } catch { this.error.set(this.language.text('stockControlAdjustmentRejectFailed')); } }
  async postAdjustment(record: InventoryAdjustment): Promise<void> { try { await this.inventory.postAdjustment(record.id, record.version); await this.refresh(); } catch { this.error.set(this.language.text('stockControlAdjustmentPostFailed')); } }
  async createCount(): Promise<void> { const warehouse = this.selectedWarehouse(); const product = this.selectedProduct(); if (!warehouse || !product || !this.actorId) return; try { await this.inventory.createCount({ companyId: warehouse.companyId, branchId: warehouse.branchId, warehouseId: warehouse.warehouseId, countType: this.countType, assignedCounterId: this.actorId, reviewerId: this.reviewerId.trim() || null, lines: this.countType === 'Cycle' ? [{ productId: product.id, unitOfMeasureId: product.baseUnitOfMeasureId, trackingIdentity: null }] : [] }); await this.refresh(); } catch { this.error.set(this.language.text('stockControlCountCreateFailed')); } }
  async submitCount(record: InventoryCount): Promise<void> { const current = this.currentLines(record); const observations = current.map(line => ({ countLineId: line.id, countedQuantity: Number(this.countedQuantities[line.id]) })).filter(item => Number.isFinite(item.countedQuantity) && item.countedQuantity >= 0); if (observations.length !== current.length) { this.error.set(this.language.text('stockControlPhysicalQuantityRequired')); return; } try { await this.inventory.submitCount(record.id, record.version, { observations }); await this.refresh(); } catch { this.error.set(this.language.text('stockControlCountObservationFailed')); } }
  async recordVarianceReason(record: InventoryCount, line: InventoryCountLine): Promise<void> { const reasonCode = this.varianceReasonCodes[line.id]; if (!reasonCode) return; try { await this.inventory.recordCountVarianceReason(record.id, record.version, line.id, reasonCode); await this.refresh(); } catch { this.error.set(this.language.text('stockControlVarianceReasonFailed')); } }
  async approveCount(record: InventoryCount): Promise<void> { try { await this.inventory.approveCount(record.id, record.version); await this.refresh(); } catch { this.error.set(this.language.text('stockControlCountApprovalFailed')); } }
  async rejectCount(record: InventoryCount): Promise<void> { try { await this.inventory.rejectCount(record.id, record.version, { reason: this.language.text('stockControlReviewerRejectionReason') }); await this.refresh(); } catch { this.error.set(this.language.text('stockControlCountRejectFailed')); } }
  async postCount(record: InventoryCount): Promise<void> { try { await this.inventory.postCount(record.id, record.version); await this.refresh(); } catch { this.error.set(this.language.text('stockControlCountPostFailed')); } }
  async recount(record: InventoryCount): Promise<void> { try { await this.inventory.recountCount(record.id, record.version, { reason: this.language.text('stockControlReviewerRecountReason') }); await this.refresh(); } catch { this.error.set(this.language.text('stockControlRecountFailed')); } }
  async resnapshot(record: InventoryCount): Promise<void> { try { await this.inventory.resnapshotCount(record.id, record.version); await this.refresh(); } catch { this.error.set(this.language.text('stockControlResnapshotFailed')); } }
  async createIssue(): Promise<void> { const warehouse = this.selectedWarehouse(); const product = this.selectedProduct(); if (!warehouse || !product || !this.issue.reasonCode || this.issue.quantity <= 0 || !this.issue.destinationUseDescription.trim()) return; try { await this.inventory.createStockIssue({ companyId: warehouse.companyId, branchId: warehouse.branchId, warehouseId: warehouse.warehouseId, destinationUseDescription: this.issue.destinationUseDescription.trim(), lines: [{ productId: product.id, unitOfMeasureId: product.baseUnitOfMeasureId, quantity: this.issue.quantity, reasonCode: this.issue.reasonCode, trackingIdentity: this.issue.trackingIdentity || null, evidenceReference: null }] }); this.issue.quantity = 0; await this.refresh(); } catch { this.error.set(this.language.text('stockControlIssueCreateFailed')); } }
  async submitIssue(record: InventoryStockIssue): Promise<void> { try { await this.inventory.submitStockIssue(record.id, record.version); await this.refresh(); } catch { this.error.set(this.language.text('stockControlIssueSubmitFailed')); } }
  async approveIssue(record: InventoryStockIssue): Promise<void> { try { await this.inventory.approveStockIssue(record.id, record.version); await this.refresh(); } catch { this.error.set(this.language.text('stockControlIssueApprovalFailed')); } }
  async rejectIssue(record: InventoryStockIssue): Promise<void> { try { await this.inventory.rejectStockIssue(record.id, record.version, { reason: this.language.text('stockControlReviewerRejectionReason') }); await this.refresh(); } catch { this.error.set(this.language.text('stockControlIssueRejectFailed')); } }
  async postIssue(record: InventoryStockIssue): Promise<void> { try { await this.inventory.postStockIssue(record.id, record.version); await this.refresh(); } catch { this.error.set(this.language.text('stockControlIssuePostFailed')); } }
  async loadAdjustmentHistory(id: string): Promise<void> { await this.loadHistory(id, () => this.inventory.adjustmentHistory(id)); }
  async loadCountHistory(id: string): Promise<void> { await this.loadHistory(id, () => this.inventory.countHistory(id)); }
  async loadIssueHistory(id: string): Promise<void> { await this.loadHistory(id, () => this.inventory.stockIssueHistory(id)); }
  private async loadHistory(id: string, loader: () => ReturnType<InventoryService['adjustmentHistory']>): Promise<void> { try { const history = await firstValueFrom(loader()); this.histories.update(current => ({ ...current, [id]: history })); } catch { this.error.set(this.language.text('stockControlHistoryUnavailable')); } }
  isEligibleCorrection(movement: InventoryMovement): boolean { return movement.sourceType === 'StockAdjustment' || movement.sourceType === 'InventoryCountVariance' || movement.sourceType === 'StockIssue'; }
  hasCorrection(movement: InventoryMovement): boolean { return this.ledgerMovements().some(item => item.correctionOfMovementId === movement.id); }
  correctionReasons(movement: InventoryMovement): InventoryReasonCode[] { const category: InventoryReasonCategory = movement.sourceType === 'StockIssue' ? 'StockIssue' : movement.sourceType === 'InventoryCountVariance' ? 'CountVariance' : 'Adjustment'; return this.reasonCatalogue().filter(item => item.category === category && item.isActive); }
  async correctMovement(movement: InventoryMovement): Promise<void> { const reasonCode = this.correctionReasonCodes[movement.id]; if (!reasonCode) { this.error.set(this.language.text('stockControlCorrectionReasonRequired')); return; } try { await this.inventory.correctMovement(movement.id, movement.version, reasonCode, this.correctionNotes[movement.id]?.trim() || undefined); await this.refresh(); } catch { this.error.set(this.language.text('stockControlCorrectionRejected')); } }
}
